class Solution {
  public long shadowPairs(int[] nums) {
    int n = nums.length;
    int[] nextSmaller = new int[n], stack = new int[n];
    int sp = 0;
    for (int i = n - 1; i >= 0; i--) {
      while (sp > 0 && nums[stack[sp - 1]] >= nums[i]) sp--;
      nextSmaller[i] = sp == 0 ? n : stack[sp - 1];
      stack[sp++] = i;
    }
    java.util.HashMap<Integer, List<Integer>> positions = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) positions.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
    long total = 0;
    for (int i = 0; i < n; i++) {
      int end = nextSmaller[i];
      long span = end - i - 1;
      List<Integer> p = positions.get(nums[i]);
      int lo = java.util.Collections.binarySearch(p, i);
      int hi = 0;
      int l = lo + 1, r = p.size();
      while (l < r) {
        int mid = (l + r) >>> 1;
        if (p.get(mid) < end) l = mid + 1;
        else r = mid;
      }
      hi = l;
      total += span - (hi - lo - 1);
    }
    return total;
  }
}
